-- Lorry Book: the whole database in one go. Generated by npm run db:bundle; do not edit.
-- Supabase → SQL Editor → New query → paste all of this → Run. Once, on an empty project.
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text);

-- ===== 20261111000100_schema
-- Phase 1 schema: masters and transactions, all scoped to one owner.
--
-- Cross-owner references are impossible by construction: every child row points at its
-- parent through a composite (id, owner_id) foreign key, so an owner cannot attach a trip
-- to someone else's vehicle, driver or party even if they guess the uuid.

create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;

create type public.app_locale   as enum ('ta', 'en');
create type public.doc_type     as enum ('fc', 'insurance', 'permit', 'pollution', 'national_permit');
create type public.trip_status  as enum ('open', 'closed', 'cancelled');
create type public.expense_kind as enum ('diesel', 'toll', 'bata', 'repair', 'fine', 'other');
create type public.payment_mode as enum ('upi', 'cash', 'cheque', 'bank');

-- Indian mobile numbers are stored the way Supabase Auth stores auth.users.phone:
-- country code, no plus sign. 919876543210.
create domain public.in_mobile as text check (value ~ '^91[6-9][0-9]{9}$');
create domain public.money as numeric(12, 2) check (value >= 0 and value < 1000000000);

create function private.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Masters
-- ---------------------------------------------------------------------------

create table public.owners (
  id            uuid primary key references auth.users (id) on delete cascade,
  name          text not null check (char_length(btrim(name)) between 1 and 80),
  business_name text not null check (char_length(btrim(business_name)) between 1 and 120),
  phone         public.in_mobile not null,
  locale        public.app_locale not null default 'ta',
  created_at    timestamptz not null default now()
);

-- The owner's phone always comes from the verified auth identity, never from the client.
create function private.owners_take_phone_from_auth() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  select u.phone into new.phone from auth.users u where u.id = new.id;
  if new.phone is null then
    raise exception 'owner % has no verified phone', new.id using errcode = '23514';
  end if;
  return new;
end $$;

create trigger owners_take_phone_from_auth
  before insert or update of phone on public.owners
  for each row execute function private.owners_take_phone_from_auth();

create table public.vehicles (
  id         uuid primary key default gen_random_uuid(),
  owner_id   uuid not null default auth.uid() references public.owners (id) on delete cascade,
  reg_number text not null check (reg_number ~ '^[A-Z0-9]{4,12}$'),
  nickname   text check (nickname is null or char_length(nickname) <= 40),
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  unique (owner_id, reg_number),
  unique (id, owner_id)
);

create table public.vehicle_documents (
  id         uuid primary key default gen_random_uuid(),
  vehicle_id uuid not null references public.vehicles (id) on delete cascade,
  doc_type   public.doc_type not null,
  expires_on date not null,
  file_url   text,
  created_at timestamptz not null default now(),
  unique (vehicle_id, doc_type)
);

create table public.drivers (
  id             uuid primary key default gen_random_uuid(),
  owner_id       uuid not null default auth.uid() references public.owners (id) on delete cascade,
  name           text not null check (char_length(btrim(name)) between 1 and 80),
  phone          public.in_mobile not null,
  licence_number text check (licence_number is null or char_length(licence_number) <= 30),
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  unique (owner_id, phone),
  unique (id, owner_id)
);
create index drivers_phone_idx on public.drivers (phone);

create table public.parties (
  id              uuid primary key default gen_random_uuid(),
  owner_id        uuid not null default auth.uid() references public.owners (id) on delete cascade,
  name            text not null check (char_length(btrim(name)) between 1 and 120),
  phone           public.in_mobile,
  place           text check (place is null or char_length(place) <= 80),
  opening_balance numeric(12, 2) not null default 0,
  created_at      timestamptz not null default now(),
  unique (id, owner_id)
);
create index parties_owner_idx on public.parties (owner_id);

-- ---------------------------------------------------------------------------
-- Transactions. Each carries client_uuid, minted on the phone, for idempotent sync.
-- ---------------------------------------------------------------------------

create table public.trips (
  id                 uuid primary key default gen_random_uuid(),
  client_uuid        uuid not null unique,
  owner_id           uuid not null default auth.uid() references public.owners (id) on delete cascade,
  vehicle_id         uuid not null,
  driver_id          uuid,
  party_id           uuid not null,
  from_place         text not null check (char_length(btrim(from_place)) between 1 and 80),
  to_place           text not null check (char_length(btrim(to_place)) between 1 and 80),
  goods              text check (goods is null or char_length(goods) <= 80),
  freight_amount     public.money not null,
  advance_from_party public.money not null default 0,
  start_odometer     integer check (start_odometer >= 0),
  end_odometer       integer check (end_odometer >= 0),
  started_on         date not null default (now() at time zone 'Asia/Kolkata')::date,
  ended_on           date,
  status             public.trip_status not null default 'open',
  notes              text check (notes is null or char_length(notes) <= 500),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),

  foreign key (vehicle_id, owner_id) references public.vehicles (id, owner_id),
  foreign key (driver_id, owner_id)  references public.drivers (id, owner_id),
  foreign key (party_id, owner_id)   references public.parties (id, owner_id),
  unique (id, owner_id, party_id),

  constraint odometer_forward check (end_odometer is null or start_odometer is null or end_odometer >= start_odometer),
  constraint ended_after_start check (ended_on is null or ended_on >= started_on),
  constraint closed_needs_end check (status <> 'closed' or (end_odometer is not null and ended_on is not null))
);
create index trips_owner_status_idx on public.trips (owner_id, status, ended_on);
create index trips_vehicle_idx on public.trips (vehicle_id);
create index trips_party_idx on public.trips (party_id);
create index trips_driver_idx on public.trips (driver_id) where status = 'open';
create trigger trips_updated_at before update on public.trips
  for each row execute function private.set_updated_at();

create table public.trip_expenses (
  id                 uuid primary key default gen_random_uuid(),
  client_uuid        uuid not null unique,
  trip_id            uuid not null references public.trips (id) on delete cascade,
  kind               public.expense_kind not null,
  amount             public.money not null,
  litres             numeric(8, 2) check (litres > 0),
  odometer           integer check (odometer >= 0),
  spent_on           date not null default (now() at time zone 'Asia/Kolkata')::date,
  entered_by_user_id uuid default auth.uid() references auth.users (id) on delete set null,
  photo_url          text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  -- Diesel always has litres (mileage depends on it); nothing else ever does.
  constraint litres_iff_diesel check ((kind = 'diesel') = (litres is not null))
);
create index trip_expenses_trip_idx on public.trip_expenses (trip_id);
create trigger trip_expenses_updated_at before update on public.trip_expenses
  for each row execute function private.set_updated_at();

create table public.payments (
  id          uuid primary key default gen_random_uuid(),
  client_uuid uuid not null unique,
  owner_id    uuid not null default auth.uid() references public.owners (id) on delete cascade,
  party_id    uuid not null,
  trip_id     uuid,
  amount      public.money not null check (amount > 0),
  mode        public.payment_mode not null,
  received_on date not null default (now() at time zone 'Asia/Kolkata')::date,
  reference   text check (reference is null or char_length(reference) <= 80),
  created_at  timestamptz not null default now(),
  foreign key (party_id, owner_id) references public.parties (id, owner_id),
  -- A payment tied to a trip must be from that trip's party (skipped when trip_id is null).
  foreign key (trip_id, owner_id, party_id) references public.trips (id, owner_id, party_id)
);
create index payments_party_idx on public.payments (party_id);

insert into supabase_migrations.schema_migrations (version, name) values ('20261111000100', 'schema') on conflict do nothing;

-- ===== 20261111000200_rls
-- Row Level Security. Every table is owner-scoped; drivers get exactly two narrow rights.
--
-- RLS filters rows, not columns. So the only way to keep freight_amount away from a driver
-- is for the driver to have no row access to trips at all. The trips table therefore has
-- an owner policy and nothing else. A driver learns about their open trip only through
-- public.driver_open_trips(), which returns no money columns.

alter table public.owners            enable row level security;
alter table public.vehicles          enable row level security;
alter table public.vehicle_documents enable row level security;
alter table public.drivers           enable row level security;
alter table public.parties           enable row level security;
alter table public.trips             enable row level security;
alter table public.trip_expenses     enable row level security;
alter table public.payments          enable row level security;

-- Nothing is readable or writable signed-out. TRUNCATE bypasses RLS, so nobody gets it.
revoke all on all tables in schema public from anon;
revoke truncate, references, trigger on all tables in schema public from authenticated;

-- ---------------------------------------------------------------------------
-- Driver identity. A driver is any signed-in user whose verified phone matches an active
-- drivers row. Security definer so the check can read auth.users and trips without
-- granting the driver any access to them.
-- ---------------------------------------------------------------------------

create function private.current_driver_ids() returns setof uuid
language sql stable security definer set search_path = '' as $$
  select d.id
  from public.drivers d
  join auth.users u on u.phone = d.phone
  where u.id = (select auth.uid()) and d.is_active
$$;

create function private.is_driver_on_open_trip(p_trip_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.trips t
    where t.id = p_trip_id
      and t.status = 'open'
      and t.driver_id in (select private.current_driver_ids())
  )
$$;

revoke all on all functions in schema private from public;
grant execute on function private.current_driver_ids() to authenticated;
grant execute on function private.is_driver_on_open_trip(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Owner policies
-- ---------------------------------------------------------------------------

create policy owners_self_select on public.owners for select to authenticated
  using (id = (select auth.uid()));
create policy owners_self_insert on public.owners for insert to authenticated
  with check (id = (select auth.uid()));
create policy owners_self_update on public.owners for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

create policy vehicles_owner on public.vehicles for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

create policy drivers_owner on public.drivers for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

create policy parties_owner on public.parties for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

create policy vehicle_documents_owner on public.vehicle_documents for all to authenticated
  using (exists (select 1 from public.vehicles v
                 where v.id = vehicle_id and v.owner_id = (select auth.uid())))
  with check (exists (select 1 from public.vehicles v
                      where v.id = vehicle_id and v.owner_id = (select auth.uid())));

-- Trips: owner only. No delete; a wrong trip is cancelled so the ledger keeps its history.
create policy trips_owner_select on public.trips for select to authenticated
  using (owner_id = (select auth.uid()));
create policy trips_owner_insert on public.trips for insert to authenticated
  with check (owner_id = (select auth.uid()));
create policy trips_owner_update on public.trips for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

create policy payments_owner on public.payments for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

create policy trip_expenses_owner on public.trip_expenses for all to authenticated
  using (exists (select 1 from public.trips t
                 where t.id = trip_id and t.owner_id = (select auth.uid())))
  with check (exists (select 1 from public.trips t
                      where t.id = trip_id and t.owner_id = (select auth.uid())));

-- ---------------------------------------------------------------------------
-- Driver policies: read and insert expenses on their own open trip. Nothing else.
-- ---------------------------------------------------------------------------

create policy trip_expenses_driver_select on public.trip_expenses for select to authenticated
  using (private.is_driver_on_open_trip(trip_id));

create policy trip_expenses_driver_insert on public.trip_expenses for insert to authenticated
  with check (
    private.is_driver_on_open_trip(trip_id)
    and entered_by_user_id = (select auth.uid())
  );

-- The driver's only window onto trips. Deliberately no freight, advance, party or profit.
create function public.driver_open_trips()
returns table (
  trip_id          uuid,
  vehicle_reg      text,
  vehicle_nickname text,
  from_place       text,
  to_place         text,
  goods            text,
  started_on       date
)
language sql stable security definer set search_path = '' as $$
  select t.id, v.reg_number, v.nickname, t.from_place, t.to_place, t.goods, t.started_on
  from public.trips t
  join public.vehicles v on v.id = t.vehicle_id
  where t.status = 'open'
    and t.driver_id in (select private.current_driver_ids())
  order by t.started_on desc
$$;

revoke execute on function public.driver_open_trips() from public, anon;
grant execute on function public.driver_open_trips() to authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261111000200', 'rls') on conflict do nothing;

-- ===== 20261111000300_views
-- Derived numbers. Never stored, never typed, never recomputed in the client.
-- Every view is security_invoker, so it runs with the caller's RLS: a driver, who has no
-- row access to trips, gets zero rows from every one of these.

create view public.trip_summary with (security_invoker = true) as
select
  t.id                                    as trip_id,
  t.owner_id,
  t.vehicle_id,
  t.driver_id,
  t.party_id,
  t.status,
  t.started_on,
  t.ended_on,
  t.from_place,
  t.to_place,
  t.freight_amount,
  t.advance_from_party,
  coalesce(e.diesel_amount, 0)            as diesel_amount,
  coalesce(e.toll_amount, 0)              as toll_amount,
  coalesce(e.bata_amount, 0)              as bata_amount,
  coalesce(e.repair_amount, 0)            as repair_amount,
  coalesce(e.fine_amount, 0)              as fine_amount,
  coalesce(e.other_amount, 0)             as other_amount,
  coalesce(e.expense_total, 0)            as expense_total,
  t.freight_amount - coalesce(e.expense_total, 0) as profit,
  t.start_odometer,
  t.end_odometer,
  t.end_odometer - t.start_odometer       as distance_km,
  coalesce(e.litres, 0)                   as litres,
  round((t.end_odometer - t.start_odometer)::numeric / nullif(e.litres, 0), 2) as mileage_kmpl
from public.trips t
left join lateral (
  select
    sum(x.amount) filter (where x.kind = 'diesel') as diesel_amount,
    sum(x.amount) filter (where x.kind = 'toll')   as toll_amount,
    sum(x.amount) filter (where x.kind = 'bata')   as bata_amount,
    sum(x.amount) filter (where x.kind = 'repair') as repair_amount,
    sum(x.amount) filter (where x.kind = 'fine')   as fine_amount,
    sum(x.amount) filter (where x.kind = 'other')  as other_amount,
    sum(x.amount)                                  as expense_total,
    sum(x.litres)                                  as litres
  from public.trip_expenses x
  where x.trip_id = t.id
) e on true;

-- Per vehicle per month (by trip end date), with the vehicle's own trailing average over
-- the six months before it.
create view public.vehicle_mileage with (security_invoker = true) as
with monthly as (
  select
    s.owner_id,
    s.vehicle_id,
    date_trunc('month', s.ended_on)::date as month,
    count(*)                              as trips,
    sum(s.distance_km)                    as distance_km,
    sum(s.litres)                         as litres
  from public.trip_summary s
  where s.status = 'closed' and s.distance_km is not null and s.litres > 0
  group by s.owner_id, s.vehicle_id, date_trunc('month', s.ended_on)
)
select
  m.owner_id,
  m.vehicle_id,
  m.month,
  m.trips,
  m.distance_km,
  m.litres,
  round(m.distance_km / m.litres, 2) as mileage_kmpl,
  round(sum(m.distance_km) over w / nullif(sum(m.litres) over w, 0), 2) as trailing_avg_kmpl
from monthly m
window w as (partition by m.vehicle_id order by m.month rows between 6 preceding and 1 preceding);

-- What each party owes: opening balance, plus net freight on closed trips (freight minus
-- the advance they paid at loading), minus payments received.
create view public.party_outstanding with (security_invoker = true) as
select
  p.id                              as party_id,
  p.owner_id,
  p.name,
  p.place,
  p.phone,
  p.opening_balance,
  coalesce(b.billed, 0)             as billed,
  coalesce(b.advance, 0)            as advance_received,
  coalesce(r.received, 0)           as payments_received,
  p.opening_balance + coalesce(b.billed, 0) - coalesce(b.advance, 0) - coalesce(r.received, 0)
                                    as outstanding
from public.parties p
left join lateral (
  select sum(t.freight_amount) as billed, sum(t.advance_from_party) as advance
  from public.trips t
  where t.party_id = p.id and t.status = 'closed'
) b on true
left join lateral (
  select sum(x.amount) as received
  from public.payments x
  where x.party_id = p.id
) r on true;

-- The two numbers on the home screen. "This month" is the calendar month in India.
create view public.owner_dashboard with (security_invoker = true) as
select
  o.id as owner_id,
  coalesce((
    select sum(s.profit)
    from public.trip_summary s
    where s.owner_id = o.id
      and s.status = 'closed'
      and s.ended_on >= date_trunc('month', now() at time zone 'Asia/Kolkata')::date
  ), 0) as month_profit,
  coalesce((
    select sum(po.outstanding)
    from public.party_outstanding po
    where po.owner_id = o.id
  ), 0) as total_outstanding
from public.owners o;

revoke all on public.trip_summary, public.vehicle_mileage, public.party_outstanding, public.owner_dashboard from anon;
grant select on public.trip_summary, public.vehicle_mileage, public.party_outstanding, public.owner_dashboard to authenticated;
revoke insert, update, delete, truncate, references, trigger
  on public.trip_summary, public.vehicle_mileage, public.party_outstanding, public.owner_dashboard
  from authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261111000300', 'views') on conflict do nothing;

-- ===== 20261112000100_phase2
-- Phase 2: trip loop + offline sync + photos.

-- ---------------------------------------------------------------------------
-- Photos: private buckets, one folder per owner (<owner uid>/...). Bunk slips and vehicle
-- documents are only ever readable by the owner who uploaded them.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('slips', 'slips', false, 2097152, array['image/jpeg', 'image/png', 'image/webp']),
  ('vehicle-docs', 'vehicle-docs', false, 4194304, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy photos_owner_select on storage.objects for select to authenticated
  using (bucket_id in ('slips', 'vehicle-docs') and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy photos_owner_insert on storage.objects for insert to authenticated
  with check (bucket_id in ('slips', 'vehicle-docs') and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy photos_owner_update on storage.objects for update to authenticated
  using (bucket_id in ('slips', 'vehicle-docs') and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id in ('slips', 'vehicle-docs') and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy photos_owner_delete on storage.objects for delete to authenticated
  using (bucket_id in ('slips', 'vehicle-docs') and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ---------------------------------------------------------------------------
-- trip_summary gains the phone-minted client_uuid (trip URLs use it, so a trip created
-- offline has the same address before and after sync) and the names lists need.
-- Existing columns keep their order; new ones are appended.
-- ---------------------------------------------------------------------------
create or replace view public.trip_summary with (security_invoker = true) as
select
  t.id                                    as trip_id,
  t.owner_id,
  t.vehicle_id,
  t.driver_id,
  t.party_id,
  t.status,
  t.started_on,
  t.ended_on,
  t.from_place,
  t.to_place,
  t.freight_amount,
  t.advance_from_party,
  coalesce(e.diesel_amount, 0)            as diesel_amount,
  coalesce(e.toll_amount, 0)              as toll_amount,
  coalesce(e.bata_amount, 0)              as bata_amount,
  coalesce(e.repair_amount, 0)            as repair_amount,
  coalesce(e.fine_amount, 0)              as fine_amount,
  coalesce(e.other_amount, 0)             as other_amount,
  coalesce(e.expense_total, 0)            as expense_total,
  t.freight_amount - coalesce(e.expense_total, 0) as profit,
  t.start_odometer,
  t.end_odometer,
  t.end_odometer - t.start_odometer       as distance_km,
  coalesce(e.litres, 0)                   as litres,
  round((t.end_odometer - t.start_odometer)::numeric / nullif(e.litres, 0), 2) as mileage_kmpl,
  t.client_uuid,
  v.reg_number                            as vehicle_reg,
  v.nickname                              as vehicle_nickname,
  p.name                                  as party_name,
  d.name                                  as driver_name,
  t.goods,
  coalesce(e.expense_count, 0)            as expense_count,
  t.created_at
from public.trips t
join public.vehicles v on v.id = t.vehicle_id
join public.parties p on p.id = t.party_id
left join public.drivers d on d.id = t.driver_id
left join lateral (
  select
    sum(x.amount) filter (where x.kind = 'diesel') as diesel_amount,
    sum(x.amount) filter (where x.kind = 'toll')   as toll_amount,
    sum(x.amount) filter (where x.kind = 'bata')   as bata_amount,
    sum(x.amount) filter (where x.kind = 'repair') as repair_amount,
    sum(x.amount) filter (where x.kind = 'fine')   as fine_amount,
    sum(x.amount) filter (where x.kind = 'other')  as other_amount,
    sum(x.amount)                                  as expense_total,
    sum(x.litres)                                  as litres,
    count(*)                                       as expense_count
  from public.trip_expenses x
  where x.trip_id = t.id
) e on true;

-- The last odometer reading we know for each vehicle: a new trip starts from here, and the
-- diesel screen offers it as the floor for the next reading.
create view public.vehicle_odometer with (security_invoker = true) as
select
  v.id as vehicle_id,
  v.owner_id,
  greatest(
    (select max(t.end_odometer) from public.trips t where t.vehicle_id = v.id and t.status = 'closed'),
    (select max(t.start_odometer) from public.trips t where t.vehicle_id = v.id and t.status <> 'cancelled'),
    (select max(x.odometer) from public.trip_expenses x join public.trips t on t.id = x.trip_id
      where t.vehicle_id = v.id and t.status <> 'cancelled')
  ) as last_odometer
from public.vehicles v;

revoke all on public.vehicle_odometer from anon;
grant select on public.vehicle_odometer to authenticated;
revoke insert, update, delete, truncate, references, trigger on public.vehicle_odometer from authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261112000100', 'phase2') on conflict do nothing;

-- ===== 20261113000100_phase3_ledger
-- Phase 3: the party ledger.
--
-- One row per thing that moved a party's balance, oldest first, with the running balance
-- computed here. Its last row always equals party_outstanding.outstanding: both count the
-- opening balance, freight and advance on closed trips only, and every payment.

create view public.party_ledger with (security_invoker = true) as
with entries as (
  select
    p.id                        as party_id,
    p.owner_id,
    'opening'::text             as kind,
    p.id                        as ref_id,
    null::uuid                  as trip_client_uuid,
    p.created_at::date          as entry_date,
    p.created_at,
    null::text                  as from_place,
    null::text                  as to_place,
    null::public.payment_mode   as mode,
    null::text                  as reference,
    p.opening_balance::numeric  as debit,
    0::numeric                  as credit
  from public.parties p
  where p.opening_balance <> 0

  union all
  select t.party_id, t.owner_id, 'trip', t.id, t.client_uuid, t.ended_on, t.created_at,
         t.from_place, t.to_place, null, null, t.freight_amount::numeric, 0
  from public.trips t
  where t.status = 'closed'

  union all
  select t.party_id, t.owner_id, 'advance', t.id, t.client_uuid, t.ended_on, t.created_at,
         t.from_place, t.to_place, null, null, 0, t.advance_from_party::numeric
  from public.trips t
  where t.status = 'closed' and t.advance_from_party > 0

  union all
  select x.party_id, x.owner_id, 'payment', x.id, null, x.received_on, x.created_at,
         null, null, x.mode, x.reference, 0, x.amount::numeric
  from public.payments x
)
select
  e.*,
  sum(e.debit - e.credit) over (
    partition by e.party_id
    order by (e.kind <> 'opening'), e.entry_date, e.created_at,
             case e.kind when 'trip' then 1 when 'advance' then 2 else 3 end, e.ref_id
    rows between unbounded preceding and current row
  ) as balance,
  row_number() over (
    partition by e.party_id
    order by (e.kind <> 'opening'), e.entry_date, e.created_at,
             case e.kind when 'trip' then 1 when 'advance' then 2 else 3 end, e.ref_id
  ) as seq
from entries e;

revoke all on public.party_ledger from anon;
grant select on public.party_ledger to authenticated;
revoke insert, update, delete, truncate, references, trigger on public.party_ledger from authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261113000100', 'phase3_ledger') on conflict do nothing;

